# EdgeAuth runs as a separate service account. Grant only Nginx access to this socket.
upstream agp_edge_auth_1d2814821bdcf07832c3c712 { server unix:/run/agp/edge-7ebf5709458f0cfc5c746317.sock; }
map $http_upgrade $agp_ec_1d2814821bdcf07832c3c712 { default upgrade; '' close; }
server {
    listen 443 ssl;
    http2 on;
    server_name app.example.net;
    ssl_certificate /etc/agp/secrets/cert_portal_v1/certificate.pem;
    ssl_certificate_key /etc/agp/secrets/cert_portal_v1/private.key;
    if ($http_host != "app.example.net") { return 421; }
    set $agp_original_method $request_method;
    location = /_agp/authorize {
        internal;
        proxy_pass http://agp_edge_auth_1d2814821bdcf07832c3c712/_agp/authorize;
        proxy_pass_request_body off;
        proxy_set_header Content-Length "";
        proxy_set_header Host $http_host;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-AGP-Client-IP $remote_addr;
        proxy_set_header X-AGP-Start "";
        proxy_set_header X-AGP-Original-URI $request_uri;
        proxy_set_header X-AGP-Original-Method $agp_original_method;
        proxy_http_version 1.1;
    }
    location = /_agp/start {
        access_log off;
        proxy_pass http://agp_edge_auth_1d2814821bdcf07832c3c712;
        proxy_set_header Host $http_host;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-AGP-Client-IP $remote_addr;
        proxy_set_header X-AGP-Start "";
        proxy_set_header X-AGP-Original-URI $request_uri;
        proxy_set_header X-AGP-Original-Method $agp_original_method;
        proxy_http_version 1.1;
    }
    location = /_agp/callback {
        access_log off;
        proxy_pass http://agp_edge_auth_1d2814821bdcf07832c3c712;
        proxy_set_header Host $http_host;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-AGP-Client-IP $remote_addr;
        proxy_set_header X-AGP-Start "";
        proxy_set_header X-AGP-Original-URI $request_uri;
        proxy_set_header X-AGP-Original-Method $agp_original_method;
        proxy_http_version 1.1;
    }
    location = /_agp/logout {
        access_log off;
        proxy_pass http://agp_edge_auth_1d2814821bdcf07832c3c712;
        proxy_set_header Host $http_host;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-AGP-Client-IP $remote_addr;
        proxy_set_header X-AGP-Start "";
        proxy_set_header X-AGP-Original-URI $request_uri;
        proxy_set_header X-AGP-Original-Method $agp_original_method;
        proxy_http_version 1.1;
    }
    location /_agp { return 404; }
    location @agp_start {
        proxy_pass http://agp_edge_auth_1d2814821bdcf07832c3c712;
        proxy_set_header Host $http_host;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-AGP-Client-IP $remote_addr;
        proxy_set_header X-AGP-Original-URI $request_uri;
        proxy_set_header X-AGP-Original-Method $agp_original_method;
        proxy_http_version 1.1;
        proxy_set_header X-AGP-Start "1";
    }
    location @agp_auth_unavailable { return 503; }
    location / {
        auth_request /_agp/authorize;
        error_page 401 = @agp_start;
        error_page 500 = @agp_auth_unavailable;
        proxy_pass http://agp_edge_auth_1d2814821bdcf07832c3c712;
        proxy_set_header Host $http_host;
        proxy_set_header X-Forwarded-Proto https;
        proxy_set_header X-AGP-Client-IP $remote_addr;
        proxy_set_header X-AGP-Start "";
        proxy_set_header X-AGP-Original-URI $request_uri;
        proxy_set_header X-AGP-Original-Method $agp_original_method;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $agp_ec_1d2814821bdcf07832c3c712;
        proxy_read_timeout 310s;
        proxy_send_timeout 30s;
    }
}
